// ─── File: src/main/java/com/bank/cdc/demo/DebeziumDemo.java ───
// Models CDC: a transaction log, a Debezium-style connector emitting before/after
// change events, and an idempotent downstream sync consumer.
package com.bank.cdc.demo;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class DebeziumDemo {

    private static final Logger log = Logger.getLogger("Debezium");
    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        TransactionLog wal = new TransactionLog();

        // The database writes to its transaction log on every committed change.
        wal.record("c", "SAV2001", null, new AccountState("SAV2001", "Rajesh Kumar", bd("1000000")));
        wal.record("c", "CUR3001", null, new AccountState("CUR3001", "Priya Sharma", bd("250000")));
        wal.record("u", "SAV2001",
            new AccountState("SAV2001", "Rajesh Kumar", bd("1000000")),
            new AccountState("SAV2001", "Rajesh Kumar", bd("950000")));   // transfer
        wal.record("d", "OLD9999",
            new AccountState("OLD9999", "Closed Account", bd("0")), null); // account closed

        DownstreamStore downstream = new DownstreamStore();
        SyncConsumer consumer = new SyncConsumer(downstream);
        DebeziumConnector debezium = new DebeziumConnector(wal, consumer);

        log.info("=== Debezium reads the log and streams every change as an event ===");
        debezium.streamAll();

        log.info("=== at-least-once replay of the last change event (idempotent apply) ===");
        debezium.replayLast();

        log.info(() -> "downstream accounts = " + downstream.snapshot());
    }
    static BigDecimal bd(String s) { return new BigDecimal(s); }
}

// ─── Would be in AccountState.java ───
class AccountState {
    final String accountId; final String holder; final BigDecimal balance;
    AccountState(String accountId, String holder, BigDecimal balance) {
        this.accountId = accountId; this.holder = holder; this.balance = balance;
    }
    public String toString() { return accountId + "(" + holder + ",Rs." + balance + ")"; }
}

// ─── Would be in ChangeEvent.java (Debezium envelope: op + before + after) ───
class ChangeEvent {
    final String op;            // "c"=create, "u"=update, "d"=delete
    final String key;           // primary key
    final AccountState before;  // null for create
    final AccountState after;   // null for delete
    ChangeEvent(String op, String key, AccountState before, AccountState after) {
        this.op = op; this.key = key; this.before = before; this.after = after;
    }
}

// ─── Would be in TransactionLog.java (models the WAL/binlog) ───
class TransactionLog {
    private final List<ChangeEvent> entries = new ArrayList<>();
    void record(String op, String key, AccountState before, AccountState after) {
        entries.add(new ChangeEvent(op, key, before, after));
    }
    List<ChangeEvent> from(int lsn) {
        return new ArrayList<>(entries.subList(lsn, entries.size()));
    }
    ChangeEvent last() { return entries.get(entries.size() - 1); }
}

// ─── Would be in DebeziumConnector.java (reads the log, emits change events) ───
class DebeziumConnector {
    private static final Logger log = Logger.getLogger("Debezium");
    private final TransactionLog wal; private final SyncConsumer consumer;
    private int lsn = 0;   // log sequence number = source offset in the WAL
    DebeziumConnector(TransactionLog wal, SyncConsumer consumer) {
        this.wal = wal; this.consumer = consumer;
    }
    void streamAll() {
        for (ChangeEvent e : wal.from(lsn)) {
            final ChangeEvent ev = e;
            log.info(() -> "CDC event op=" + ev.op + " key=" + ev.key
                    + " before=" + ev.before + " after=" + ev.after);
            consumer.apply(ev);     // publish to Kafka → downstream
            lsn++;
        }
    }
    void replayLast() {
        log.warning("Debezium restart → replaying last WAL event (at-least-once)");
        consumer.apply(wal.last());
    }
}

// ─── Would be in DownstreamStore.java (search index / replica DB target) ───
class DownstreamStore {
    private final Map<String, AccountState> byKey = new LinkedHashMap<>();
    void put(AccountState s) { byKey.put(s.accountId, s); }
    void remove(String key) { byKey.remove(key); }
    Map<String, AccountState> snapshot() { return byKey; }
}

// ─── Would be in SyncConsumer.java (idempotent apply by primary key) ───
class SyncConsumer {
    private static final Logger log = Logger.getLogger("Debezium");
    private final DownstreamStore store;
    SyncConsumer(DownstreamStore store) { this.store = store; }
    void apply(ChangeEvent e) {
        switch (e.op) {
            case "c", "u" -> {       // create/update → upsert the "after" state (idempotent)
                store.put(e.after);
                log.info(() -> "applied upsert key=" + e.key + " -> " + e.after);
            }
            case "d" -> {            // delete → remove by key (idempotent)
                store.remove(e.key);
                log.info(() -> "applied delete key=" + e.key);
            }
            default -> log.warning(() -> "unknown op " + e.op);
        }
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
